import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_n_12(n):
    if n == 1:
        return 1 # Handle n=1 explicitly, though we start at n=21

    factors = prime_factorization(n)

    # tau(n^12) = product (12*a_i + 1)
    tau_val = 1
    for exponent in factors.values():
        tau_val *= (12 * exponent + 1)
    return tau_val

solutions = []
results = {}

# Check n from 21 to 50
for n in range(21, 51):
    tau_n_12 = calculate_tau_n_12(n)

    if n == tau_n_12:
        solutions.append(n)

    results[n] = {
        "n": n,
        "tau(n^12)": tau_n_12,
        "match": n == tau_n_12
    }

print("--- Results Dictionary ---")
print(results)
print("\n--- Solutions Found ---")
print(solutions)
